def tri(n):
    if n == 0:
        return [3]
    if n == 1:
        return [3, 2]

    sequence = [3, 2]
    for i in range(2, n + 1):
        if i % 2 == 0:
            next_value = 1 + i / 2
        else:
            next_value = sequence[i - 1] + sequence[i - 2] + sequence[i + 1] if i < len(sequence) else 1 + (i + 1) / 2
        sequence.append(next_value)

    return sequence[:n + 1]

# Example usage:
print(tri(3))  # Output: [3, 2, 8, 11]
