def bf(planet1, planet2):
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]

    def in_range(planet):
        return planet in planets

    def index_of(planet):
        return planets.index(planet)

    if not in_range(planet1) or not in_range(planet2):
        return ()

    start = index_of(planet1)
    end = index_of(planet2)

    if start > end:
        start, end = end, start

    return tuple(planets[start+1:end])
